import sys

def bsearch(row, target):
    lo, hi = 0, len(row) - 1
    while lo <= hi:
        mid = (lo + hi) // 2
        if row[mid] == target:
            return True
        elif row[mid] < target:
            lo = mid + 1
        else:
            hi = mid - 1
    return False

def search_opt(mat, target):
    for row in mat:
        if row and row[0] <= target <= row[-1] and bsearch(row, target):
            return True
    return False

