import sys

def search_best(mat, m, n, target):
    lo, hi = 0, m * n - 1
    while lo <= hi:
        mid = (lo + hi) // 2
        v = mat[mid // n][mid % n]
        if v == target:
            return True
        elif v < target:
            lo = mid + 1
        else:
            hi = mid - 1
    return False

if __name__ == '__main__':
    data = sys.stdin.read().split()
    if not data:
        sys.exit(0)
    m, n = int(data[0]), int(data[1])
    mat = []
    idx = 2
    for _ in range(m):
        mat.append(list(map(int, data[idx:idx + n])))
        idx += n
    target = int(data[idx])
    print('true' if search_best(mat, m, n, target) else 'false')
